<form method="post" class="panel form-card"><div class="panel-head"><div><h2>Informasi pelapor</h2><p>Lengkapi data agar teknisi dapat menangani dengan tepat.</p></div></div><div class="form-grid"><label>Nama pelapor<input name="nama_pelapor" value="<?= html_escape($this->session->userdata('user')['nama']) ?>" required></label><label>Unit kerja<select name="unit_id" required><option value="">Pilih unit</option><?php foreach($units as $u): ?><option value="<?= $u->id ?>" <?= $this->session->userdata('user')['unit_id']==$u->id?'selected':'' ?>><?= html_escape($u->nama_unit) ?></option><?php endforeach; ?></select></label><label>Jenis keluhan<select name="jenis_keluhan_id" required><?php foreach($types as $t): ?><option value="<?= $t->id ?>"><?= html_escape($t->nama_jenis) ?></option><?php endforeach; ?></select></label><label>Jenis lainnya (opsional)<input name="jenis_lainnya" placeholder="Jika memilih Lainnya"></label></div><hr><h2>Detail keluhan</h2><div class="form-grid single"><label>Deskripsi aduan<textarea name="deskripsi_aduan" required placeholder="Jelaskan masalah, perangkat, dan dampaknya..."></textarea></label><label>Keluhan pengguna<textarea name="keluhan_pengguna" placeholder="Contoh: laptop lambat sejak pagi"></textarea></label><label>Kelengkapan barang<textarea name="kelengkapan_barang" placeholder="Contoh: Laptop, charger, mouse"></textarea></label></div><div class="form-actions"><a class="button ghost" href="<?= site_url('tickets') ?>">Batal</a><button class="button primary">Kirim laporan →</button></div></form>
